template:
⟦attr_slot⟧
struct Color { r: u8, g: u32, b: u8 }

fn red_channel(ptr: *const Color) -> u8 {
    unsafe {
        let byte_ptr = ptr as ⟦cast_slot⟧;
        *byte_ptr
    }
}

fn main() {
    let c = Color { r: 255, g: 0, b: 0 };
    println!("{}", red_channel(&c as *const Color));
}

tests:
#[test]
fn reads_red_byte() {
    let c = Color { r: 255, g: 0, b: 0 };
    assert_eq!(red_channel(&c as *const Color), 255);
}
